create extension if not exists pgcrypto;
create table if not exists profiles (id uuid primary key references auth.users on delete cascade, display_name text, avatar_url text, preferences jsonb not null default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists vehicles (slug text primary key, status text not null, make text not null, model text not null, generation text, type text not null, years jsonb not null, tier text not null, summary text not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists vehicle_specs (id uuid primary key default gen_random_uuid(), vehicle_slug text references vehicles on delete cascade, key text not null, value jsonb not null, unit text, source_url text not null, verified_at timestamptz, unique(vehicle_slug,key));
create table if not exists vehicle_assets (id uuid primary key default gen_random_uuid(), vehicle_slug text references vehicles on delete cascade, kind text not null, path text not null, status text not null default 'uploaded', provenance jsonb not null default '{}', metrics jsonb not null default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists collections (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, name text not null, visibility text not null default 'private', vehicle_slugs text[] not null default '{}', notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists comparisons (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, name text, vehicle_slugs text[] not null, unit_preference text default 'source', share_token uuid default gen_random_uuid(), created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists threads (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, title text, messages jsonb not null default '[]', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists recent_views (user_id uuid references auth.users on delete cascade, vehicle_slug text references vehicles on delete cascade, viewed_at timestamptz default now(), primary key(user_id,vehicle_slug));
create table if not exists suggestions (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users on delete set null, vehicle text not null, reason text, source_url text, status text not null default 'new', created_at timestamptz default now());
create table if not exists audit_events (id bigint generated always as identity primary key, actor_id uuid references auth.users on delete set null, action text not null, entity_type text not null, entity_id text not null, payload jsonb not null default '{}', created_at timestamptz default now());
alter table profiles enable row level security; alter table collections enable row level security; alter table comparisons enable row level security; alter table threads enable row level security; alter table recent_views enable row level security; alter table suggestions enable row level security;
create policy "own profile" on profiles for all using (auth.uid()=id) with check (auth.uid()=id);
create policy "own collections" on collections for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "own comparisons" on comparisons for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "own threads" on threads for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "own recent views" on recent_views for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "submit suggestions" on suggestions for insert with check (auth.uid()=user_id or user_id is null);
